1	// Fire-and-forget batched event queue — nunca bloqueia UX.
2	// Acumula eventos e faz flush em lote via Supabase REST.
3	// Usa sendBeacon no beforeunload para confiabilidade mobile.
4	
5	import { supabase } from '@/integrations/supabase/client';
6	
7	export interface GidapeEvent {
8	  user_id: string;
9	  session_id: string;
10	  event_type:
11	    | 'page_enter'
12	    | 'page_exit'
13	    | 'feature_use'
14	    | 'search_query'
15	    | 'mia_opened'
16	    | 'mia_suggestion_acted'
17	    | 'click'
18	    | 'form_submit'
19	    | 'error_seen';
20	  page: string;
21	  properties?: Record<string, unknown>;
22	  loja_id?: number | null;
23	  role?: string | null;
24	  device_type?: string;
25	}
26	
27	const FLUSH_INTERVAL_MS = 8_000;
28	const MAX_BATCH = 50;
29	
30	const _queue: GidapeEvent[] = [];
31	let _flushTimer: ReturnType<typeof setTimeout> | null = null;
32	let _initialized = false;
33	
34	function getDeviceType(): string {
35	  const w = window.innerWidth;
36	  if (w < 768) return 'mobile';
37	  if (w < 1024) return 'tablet';
38	  return 'desktop';
39	}
40	
41	// Cache do access token do user — necessário no beforeunload flush, onde a RLS
42	// de gidape_events exige auth.uid()=user_id. A anon key não satisfaz isso.
43	let _accessToken: string | null = null;
44	let _tokenSubscribed = false;
45	
46	function _subscribeToken(): void {
47	  if (_tokenSubscribed) return;
48	  _tokenSubscribed = true;
49	  (supabase as any).auth.getSession().then(({ data }: any) => {
50	    _accessToken = data?.session?.access_token ?? null;
51	  }).catch(() => {});
52	  (supabase as any).auth.onAuthStateChange((_event: string, session: any) => {
53	    _accessToken = session?.access_token ?? null;
54	  });
55	}
56	
57	async function _flush(): Promise<void> {
58	  if (_queue.length === 0) return;
59	  const batch = _queue.splice(0, MAX_BATCH);
60	  try {
61	    await (supabase as any).from('gidape_events').insert(
62	      batch.map((e) => ({ ...e, device_type: e.device_type ?? getDeviceType() }))
63	    );
64	  } catch {
65	    // Fire-and-forget — never throw, never break UX
66	  }
67	}
68	
69	function _scheduleFlush(): void {
70	  if (_flushTimer) return;
71	  _flushTimer = setTimeout(() => {
72	    _flushTimer = null;
73	    _flush();
74	  }, FLUSH_INTERVAL_MS);
75	}
76	
77	function _initBeforeUnload(): void {
78	  if (_initialized) return;
79	  _initialized = true;
80	  _subscribeToken();
81	
82	  // visibilitychange (hidden) é mais confiável que beforeunload em mobile/PWA
83	  // — beforeunload nem sempre dispara quando o app vai pra background no iOS/Android.
84	  const flushOnExit = () => {
85	    if (_queue.length === 0) return;
86	    const batch = _queue.splice(0);
87	    const url = `${import.meta.env.VITE_SUPABASE_URL}/rest/v1/gidape_events`;
88	    const payload = JSON.stringify(batch.map((e) => ({ ...e, device_type: e.device_type ?? getDeviceType() })));
89	    // Usa o access token do user (RLS exige auth.uid()=user_id); fallback anon.
90	    const token = _accessToken ?? import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
91	    const headers: Record<string, string> = {
92	      'Content-Type': 'application/json',
93	      apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
94	      Authorization: `Bearer ${token}`,
95	      Prefer: 'return=minimal',
96	    };
97	    try {
98	      fetch(url, { method: 'POST', headers, body: payload, keepalive: true }).catch(() => {});
99	    } catch {
100	      navigator.sendBeacon?.(url, new Blob([payload], { type: 'application/json' }));
101	    }
102	  };
103	
104	  window.addEventListener('beforeunload', flushOnExit);
105	  document.addEventListener('visibilitychange', () => {
106	    if (document.visibilityState === 'hidden') flushOnExit();
107	  });
108	}
109	
110	export function enqueueEvent(event: GidapeEvent): void {
111	  _initBeforeUnload();
112	  _queue.push(event);
113	  if (_queue.length >= MAX_BATCH) {
114	    if (_flushTimer) {
115	      clearTimeout(_flushTimer);
116	      _flushTimer = null;
117	    }
118	    _flush();
119	  } else {
120	    _scheduleFlush();
121	  }
122	}
123	
124	/** Flush imediato — chamar quando necessário (ex: logout) */
125	export function flushAnalytics(): Promise<void> {
126	  if (_flushTimer) {
127	    clearTimeout(_flushTimer);
128	    _flushTimer = null;
129	  }
130	  return _flush();
131	}
