1	// Hook global de rastreamento comportamental para MIA.
2	// Captura: page_enter/exit (com dwell_ms, scroll_pct, next_page),
3	// feature_use, search_query, mia_opened, mia_suggestion_acted.
4	//
5	// Usado no DashboardLayout — não instanciar em páginas individuais.
6	
7	import { useEffect, useRef, useCallback } from 'react';
8	import { useLocation } from 'react-router-dom';
9	import { useAuth } from '@/hooks/useAuth';
10	import { useStore } from '@/shared/contexts/StoreContext';
11	import { enqueueEvent, type GidapeEvent } from './analyticsQueue';
12	
13	const SESSION_KEY = 'momma_behavior_session';
14	
15	function getSessionId(): string {
16	  let sid = sessionStorage.getItem(SESSION_KEY);
17	  if (!sid) {
18	    sid = crypto.randomUUID();
19	    sessionStorage.setItem(SESSION_KEY, sid);
20	  }
21	  return sid;
22	}
23	
24	function getDeviceType(): string {
25	  const w = window.innerWidth;
26	  if (w < 768) return 'mobile';
27	  if (w < 1024) return 'tablet';
28	  return 'desktop';
29	}
30	
31	function getScrollPct(): number {
32	  const el = document.documentElement;
33	  const scrollable = el.scrollHeight - el.clientHeight;
34	  if (scrollable <= 0) return 100;
35	  return Math.round((window.scrollY / scrollable) * 100);
36	}
37	
38	export function useMiaBehaviorTracker() {
39	  const { user } = useAuth();
40	  const location = useLocation();
41	  const { selectedStore } = useStore() as any;
42	
43	  const pageEnterRef = useRef<number>(performance.now());
44	  const prevPageRef = useRef<string>('');
45	  const sessionId = getSessionId();
46	
47	  const makeBase = useCallback((): Omit<GidapeEvent, 'event_type' | 'properties'> => ({
48	    user_id: user?.id ?? '',
49	    session_id: sessionId,
50	    page: location.pathname,
51	    loja_id: selectedStore?.id ?? null,
52	    role: (user as any)?.role ?? null,
53	    device_type: getDeviceType(),
54	  }), [user, sessionId, location.pathname, selectedStore]);
55	
56	  // page_exit para página anterior + page_enter para nova
57	  useEffect(() => {
58	    if (!user?.id) return;
59	
60	    const now = performance.now();
61	    const prevPage = prevPageRef.current;
62	    const currentPage = location.pathname;
63	
64	    if (prevPage && prevPage !== currentPage) {
65	      const dwell_ms = Math.round(now - pageEnterRef.current);
66	      enqueueEvent({
67	        ...makeBase(),
68	        page: prevPage,
69	        event_type: 'page_exit',
70	        properties: {
71	          dwell_ms,
72	          scroll_pct: getScrollPct(),
73	          next_page: currentPage,
74	        },
75	      });
76	    }
77	
78	    enqueueEvent({
79	      ...makeBase(),
80	      event_type: 'page_enter',
81	      properties: { referrer: prevPage || null },
82	    });
83	
84	    pageEnterRef.current = now;
85	    prevPageRef.current = currentPage;
86	  // eslint-disable-next-line react-hooks/exhaustive-deps
87	  }, [location.pathname, user?.id]);
88	
89	  /** Rastreia uso de feature específica */
90	  const trackFeature = useCallback((featureId: string, action: string, extra?: Record<string, unknown>) => {
91	    if (!user?.id) return;
92	    enqueueEvent({
93	      ...makeBase(),
94	      event_type: 'feature_use',
95	      properties: { feature_id: featureId, action, ...extra },
96	    });
97	  }, [makeBase, user?.id]);
98	
99	  /** Rastreia query de busca */
100	  const trackSearch = useCallback((term: string, resultCount: number, clickedResult?: string) => {
101	    if (!user?.id) return;
102	    enqueueEvent({
103	      ...makeBase(),
104	      event_type: 'search_query',
105	      properties: { term: term.slice(0, 200), result_count: resultCount, clicked_result: clickedResult ?? null },
106	    });
107	  }, [makeBase, user?.id]);
108	
109	  /** Rastreia abertura do chat MIA */
110	  const trackMiaOpened = useCallback((trigger: 'fab' | 'shortcut' | 'proactive' = 'fab') => {
111	    if (!user?.id) return;
112	    enqueueEvent({
113	      ...makeBase(),
114	      event_type: 'mia_opened',
115	      properties: { trigger },
116	    });
117	  }, [makeBase, user?.id]);
118	
119	  /** Rastreia se sugestão da MIA foi aceita ou ignorada */
120	  const trackMiaSuggestion = useCallback((suggestionId: string, acted: boolean) => {
121	    if (!user?.id) return;
122	    enqueueEvent({
123	      ...makeBase(),
124	      event_type: 'mia_suggestion_acted',
125	      properties: { suggestion_id: suggestionId, acted },
126	    });
127	  }, [makeBase, user?.id]);
128	
129	  return { trackFeature, trackSearch, trackMiaOpened, trackMiaSuggestion };
130	}
