1	// Rastreamento de sessões sem MIA (Padrão 2 — Counterfactual).
2	// Registra o que usuários fazem quando NÃO usam o chat MIA.
3	// Permite medir impacto real da IA: compara sessões com vs sem assistência.
4	//
5	// Usado no DashboardLayout junto com useMiaBehaviorTracker.
6	
7	import { useEffect, useRef, useCallback } from 'react';
8	import { useLocation } from 'react-router-dom';
9	import { useAuth } from '@/hooks/useAuth';
10	import { supabase } from '@/integrations/supabase/client';
11	
12	const SESSION_KEY = 'momma_cf_session';
13	const FLUSH_DEBOUNCE_MS = 5_000;
14	
15	interface CfSession {
16	  id: string;
17	  mia_opened: boolean;
18	  pages: string[];
19	  clicks: number;
20	  dwell_samples: number[];
21	  started_at: number;
22	  last_page_enter: number;
23	}
24	
25	function loadSession(userId: string): CfSession {
26	  try {
27	    const raw = sessionStorage.getItem(SESSION_KEY);
28	    if (raw) return JSON.parse(raw);
29	  } catch {}
30	  const id = crypto.randomUUID();
31	  const session: CfSession = {
32	    id,
33	    mia_opened: false,
34	    pages: [],
35	    clicks: 0,
36	    dwell_samples: [],
37	    started_at: Date.now(),
38	    last_page_enter: Date.now(),
39	  };
40	  sessionStorage.setItem(SESSION_KEY, JSON.stringify(session));
41	  return session;
42	}
43	
44	function saveSession(s: CfSession): void {
45	  sessionStorage.setItem(SESSION_KEY, JSON.stringify(s));
46	}
47	
48	async function persistSession(s: CfSession, userId: string, ended = false): Promise<void> {
49	  const avgDwell = s.dwell_samples.length > 0
50	    ? Math.round(s.dwell_samples.reduce((a, b) => a + b, 0) / s.dwell_samples.length)
51	    : null;
52	  const payload = {
53	    id: s.id,
54	    user_id: userId,
55	    session_id: s.id,
56	    started_at: new Date(s.started_at).toISOString(),
57	    ended_at: ended ? new Date().toISOString() : undefined,
58	    duration_ms: ended ? Date.now() - s.started_at : undefined,
59	    pages_visited: [...new Set(s.pages)],
60	    page_count: s.pages.length,
61	    mia_opened: s.mia_opened,
62	    avg_dwell_ms: avgDwell,
63	    total_clicks: s.clicks,
64	  };
65	  try {
66	    await (supabase as any).from('mia_counterfactual_sessions').upsert(payload, {
67	      onConflict: 'session_id',
68	      ignoreDuplicates: false,
69	    });
70	  } catch {
71	    // fire-and-forget
72	  }
73	}
74	
75	export function useCounterfactualTracker() {
76	  const { user } = useAuth();
77	  const location = useLocation();
78	  const sessionRef = useRef<CfSession | null>(null);
79	  const flushTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
80	
81	  const getOrInit = useCallback((): CfSession | null => {
82	    if (!user?.id) return null;
83	    if (!sessionRef.current) {
84	      sessionRef.current = loadSession(user.id);
85	    }
86	    return sessionRef.current;
87	  }, [user?.id]);
88	
89	  const schedulePersist = useCallback((ended = false) => {
90	    if (!user?.id) return;
91	    const s = sessionRef.current;
92	    if (!s) return;
93	    if (flushTimer.current) clearTimeout(flushTimer.current);
94	    flushTimer.current = setTimeout(() => {
95	      if (sessionRef.current) persistSession(sessionRef.current, user!.id!, ended);
96	    }, ended ? 0 : FLUSH_DEBOUNCE_MS);
97	  // eslint-disable-next-line react-hooks/exhaustive-deps
98	  }, [user?.id, user]);
99	
100	  // Rastreia mudança de página
101	  useEffect(() => {
102	    const s = getOrInit();
103	    if (!s) return;
104	    const now = Date.now();
105	    const dwell = now - s.last_page_enter;
106	    if (dwell > 500 && dwell < 3_600_000) {
107	      s.dwell_samples.push(dwell);
108	    }
109	    s.pages.push(location.pathname);
110	    s.last_page_enter = now;
111	    saveSession(s);
112	    schedulePersist();
113	  // eslint-disable-next-line react-hooks/exhaustive-deps
114	  }, [location.pathname, user?.id]);
115	
116	  // Click tracking global
117	  useEffect(() => {
118	    if (!user?.id) return;
119	    const handler = () => {
120	      const s = getOrInit();
121	      if (!s) return;
122	      s.clicks++;
123	      saveSession(s);
124	    };
125	    document.addEventListener('click', handler, { passive: true });
126	    return () => document.removeEventListener('click', handler);
127	  }, [user?.id, getOrInit]);
128	
129	  // Flush no beforeunload
130	  useEffect(() => {
131	    if (!user?.id) return;
132	    const handler = () => {
133	      const s = sessionRef.current;
134	      if (!s) return;
135	      const dwell = Date.now() - s.last_page_enter;
136	      if (dwell > 500) s.dwell_samples.push(dwell);
137	      s.pages.push(location.pathname);
138	      persistSession(s, user!.id!, true);
139	    };
140	    window.addEventListener('beforeunload', handler);
141	    return () => window.removeEventListener('beforeunload', handler);
142	  // eslint-disable-next-line react-hooks/exhaustive-deps
143	  }, [user?.id]);
144	
145	  /** Chamar quando MIA for aberta — marca sessão como assistida */
146	  const markMiaOpened = useCallback(() => {
147	    const s = getOrInit();
148	    if (!s) return;
149	    s.mia_opened = true;
150	    saveSession(s);
151	    schedulePersist();
152	  }, [getOrInit, schedulePersist]);
153	
154	  return { markMiaOpened };
155	}
