1	// Badge + toast de proatividade da MIA.
2	//
3	// - Conta itens não-entregues em mia_proactive_queue (badge no item MIA da sidebar).
4	// - Realtime: quando um item de alta prioridade chega, salta um toast na hora,
5	//   mesmo sem o usuário abrir a MIA. É o que torna a MIA realmente proativa
6	//   (push, não pull).
7	// - Reseta o badge quando a MIA consome a fila (evento 'mia-proactive-consumed').
8	
9	import { useEffect, useState, useCallback } from 'react';
10	import { useNavigate } from 'react-router-dom';
11	import { useAuth } from '@/hooks/useAuth';
12	import { supabase } from '@/integrations/supabase/client';
13	import { toast } from 'sonner';
14	import { useMiaProactiveEnabled } from '@/features/mia/lib/proactiveConfig';
15	
16	const HIGH_PRIORITY = 2; // priority <= 2 → toast imediato
17	
18	export function useMiaProactiveBadge(): number {
19	  const { user } = useAuth();
20	  const navigate = useNavigate();
21	  const proactiveEnabled = useMiaProactiveEnabled();
22	  const [count, setCount] = useState(0);
23	
24	  const refetch = useCallback(async () => {
25	    if (!user?.id || !proactiveEnabled) {
26	      setCount(0);
27	      return;
28	    }
29	    try {
30	      const { count: c } = await (supabase as any)
31	        .from('mia_proactive_queue')
32	        .select('id', { count: 'exact', head: true })
33	        .eq('user_id', user.id)
34	        .eq('delivered', false)
35	        .gt('expires_at', new Date().toISOString());
36	      setCount(c ?? 0);
37	    } catch {
38	      setCount(0);
39	    }
40	  }, [user?.id, proactiveEnabled]);
41	
42	  // Fetch inicial + reset quando a MIA consome a fila
43	  useEffect(() => {
44	    refetch();
45	    const onConsumed = () => setCount(0);
46	    window.addEventListener('mia-proactive-consumed', onConsumed);
47	    return () => window.removeEventListener('mia-proactive-consumed', onConsumed);
48	  }, [refetch]);
49	
50	  // Realtime: novo item → incrementa badge + toast se alta prioridade
51	  useEffect(() => {
52	    if (!user?.id || !proactiveEnabled) return;
53	    const channel = supabase
54	      .channel(`mia-proactive-${user.id}`)
55	      .on(
56	        'postgres_changes',
57	        { event: 'INSERT', schema: 'public', table: 'mia_proactive_queue', filter: `user_id=eq.${user.id}` },
58	        (payload: any) => {
59	          const item = payload.new;
60	          if (!item || item.delivered) return;
61	          setCount((c) => c + 1);
62	          if ((item.priority ?? 5) <= HIGH_PRIORITY) {
63	            toast(item.title || 'MIA', {
64	              description: String(item.body || '').slice(0, 160),
65	              action: { label: 'Ver', onClick: () => navigate('/mia') },
66	              duration: 10000,
67	            });
68	          }
69	        },
70	      )
71	      .subscribe();
72	    return () => {
73	      supabase.removeChannel(channel);
74	    };
75	  }, [user?.id, navigate, proactiveEnabled]);
76	
77	  return proactiveEnabled ? count : 0;
78	}
