1	// Kill-switch da proatividade da MIA (lê mia_runtime_config.proactive_enabled).
2	//
3	// Default OFF: enquanto a flag não carrega ou está false, NADA proativo aparece
4	// (badge, toast, greeting). A captura/aprendizado seguem normalmente.
5	// Ligar em ~2026-06-16 via: update mia_runtime_config set value='true' where key='proactive_enabled'.
6	
7	import { useEffect, useState } from 'react';
8	import { supabase } from '@/integrations/supabase/client';
9	
10	let _enabled = false;
11	let _loaded = false;
12	let _inflight: Promise<boolean> | null = null;
13	
14	async function _fetchFlag(): Promise<boolean> {
15	  try {
16	    const { data } = await (supabase as any)
17	      .from('mia_runtime_config')
18	      .select('value')
19	      .eq('key', 'proactive_enabled')
20	      .maybeSingle();
21	    // value é jsonb boolean (true/false)
22	    _enabled = data?.value === true || data?.value === 'true';
23	  } catch {
24	    _enabled = false;
25	  }
26	  _loaded = true;
27	  return _enabled;
28	}
29	
30	/** Garante que a flag foi carregada (cache compartilhado, 1 fetch). */
31	export function ensureProactiveConfig(): Promise<boolean> {
32	  if (_loaded) return Promise.resolve(_enabled);
33	  if (!_inflight) _inflight = _fetchFlag();
34	  return _inflight;
35	}
36	
37	/** Leitura síncrona do cache (false até carregar). */
38	export function isProactiveEnabledSync(): boolean {
39	  return _enabled;
40	}
41	
42	/** Hook reativo: retorna se a proatividade está ligada (default false). */
43	export function useMiaProactiveEnabled(): boolean {
44	  const [enabled, setEnabled] = useState(_enabled);
45	  useEffect(() => {
46	    let active = true;
47	    ensureProactiveConfig().then((v) => {
48	      if (active) setEnabled(v);
49	    });
50	    return () => { active = false; };
51	  }, []);
52	  return enabled;
53	}
