1	// Consumer da fila proativa da MIA (mia_proactive_queue).
2	//
3	// Os crons (mia-morning-digest, mia-anomaly-watcher, mia-pattern-analyzer)
4	// gravam mensagens proativas nessa fila. Quando o usuário abre a MIA,
5	// buscamos os itens não-entregues, surgimos com eles como saudação
6	// contextual, e marcamos como entregues para não repetir.
7	
8	import { supabase } from '@/integrations/supabase/client';
9	
10	export interface ProactiveItem {
11	  id: string;
12	  type: 'morning_digest' | 'anomaly' | 'pattern_insight' | 'loop_friction';
13	  title: string;
14	  body: string;
15	  priority: number;
16	  context: Record<string, unknown>;
17	}
18	
19	/** Busca itens proativos não-entregues e não-expirados, por prioridade. */
20	export async function fetchPendingProactive(userId: string): Promise<ProactiveItem[]> {
21	  if (!userId) return [];
22	  try {
23	    const { data, error } = await (supabase as any)
24	      .from('mia_proactive_queue')
25	      .select('id, type, title, body, priority, context')
26	      .eq('user_id', userId)
27	      .eq('delivered', false)
28	      .gt('expires_at', new Date().toISOString())
29	      .order('priority', { ascending: true })
30	      .order('created_at', { ascending: false })
31	      .limit(5);
32	    if (error) return [];
33	    return (data ?? []) as ProactiveItem[];
34	  } catch {
35	    return [];
36	  }
37	}
38	
39	/** Marca itens como entregues — fire-and-forget. */
40	export async function markProactiveDelivered(ids: string[]): Promise<void> {
41	  if (!ids.length) return;
42	  try {
43	    await (supabase as any)
44	      .from('mia_proactive_queue')
45	      .update({ delivered: true, delivered_at: new Date().toISOString() })
46	      .in('id', ids);
47	  } catch {
48	    // never break UX
49	  }
50	}
51	
52	/** Formata os itens proativos num único bloco markdown de saudação. */
53	export function formatProactiveGreeting(items: ProactiveItem[]): string {
54	  if (!items.length) return '';
55	  const icon: Record<ProactiveItem['type'], string> = {
56	    morning_digest: '☀️',
57	    anomaly: '⚠️',
58	    pattern_insight: '💡',
59	    loop_friction: '💡',
60	  };
61	  const parts = items.map((it) => {
62	    const i = icon[it.type] ?? '📌';
63	    // morning_digest já vem com saudação pronta do LLM — não duplica título
